create table "public"."course_reviews" (
  "id"         bigint                   generated by default as identity not null,
  "course_id"  bigint                   not null,
  "learner_id" uuid,
  "rating"     integer                  not null,
  "review"     text,
  "status"     text                     not null default 'published'::text,
  "created_at" timestamp with time zone not null default now(),
  constraint "course_reviews_pkey" primary key (id),
  constraint "course_reviews_rating_check" check (((rating >= 1) AND (rating <= 5))),
  constraint "course_reviews_status_check" check ((status = ANY (ARRAY['pending'::text, 'published'::text, 'hidden'::text]))),
  constraint "course_reviews_course_id_fkey" foreign key (course_id) references public.learning_courses(id) on delete cascade,
  constraint "course_reviews_learner_id_fkey" foreign key (learner_id) references public.profiles(id) on delete set null
);

alter table "public"."course_reviews"
  enable row level security;

create policy "Published reviews are public" on "public"."course_reviews"
  for select
  to "anon", "authenticated"
  using ((status = 'published'::text));

grant select on table "public"."course_reviews" to "anon", "authenticated";

grant delete, insert, maintain, references, select, trigger, truncate, update on table "public"."course_reviews" to "postgres", "service_role";
